 class="consistency-search"><label>Buscar</label><input type="search" name="search" value="{{ $filters['search']??'' }}" placeholder="Veículo, placa, código ou ocorrência…"></div><div class="consistency-filter-actions"><button>Filtrar</button><a href="{{ route('consistency.index') }}">Limpar</a></div></form><section class="consistency-list">@forelse($alerts as $a)@php($v=$a->consistencyVehicle)@php($d=$a->details??[])<article class="consistency-alert"><div class="consistency-alert-main"><div class="consistency-alert-top"><span class="consistency-severity severity-{{ $a->severity }}">{{ ['critical'=>'Crítico','warning'=>'Alerta','review'=>'Revisar','info'=>'Informativo'][$a->severity] }}</span><span class="consistency-context-badge">{{ $a->context_type==='historical'?'Histórico':'Atual' }}</span><span class="consistency-detection">{{ $a->last_detected_at?->gte($a->last_scanned_at)?'Ainda detectado':'Não encontrado na última varredura' }}</span></div>@if($v)<strong class="consistency-vehicle">{{ $v->name }} · {{ $v->plate ?: ($v->asset_code ? 'Código: '.$v->asset_code : ($v->renavam ?: $v->serial_number)) }}</strong>@endif<h2>{{ $a->title }}</h2><p>{{ $a->summary }}</p>@if($a->rule_key==='vehicle_reading_regression')<p class="consistency-detail">{{ number_format($d['previous']['value']??0,0,',','.') }} → {{ number_format($d['current']['value']??0,0,',','.') }} {{ $d['type']==='hours'?'hr':'km' }} · Queda: {{ number_format($d['magnitude']??0,0,',','.') }}</p>@elseif($a->rule_key==='vehicle_current_counter_divergence')<p class="consistency-detail">Atual: {{ number_format($d['current']??0,0,',','.') }} · Última válida: {{ number_format($d['last_valid']??0,0,',','.') }} · Diferença: {{ number_format($d['difference']??0,0,',','.') }}</p>@elseif($a->rule_key==='vehicle_repeated_reading')<p class="consistency-detail">Leitura: {{ number_format($d['value']??0,0,',','.') }} · Ocorrências: {{ $d['events']??0 }} · {{ $d['from']??'' }} a {{ $d['to']??'' }}</p>@elseif($a->rule_key==='fuel_impossible_consumption')<p class="consistency-detail">Distância: {{ $d['distance']??'' }} · Consumo: {{ $d['km_per_liter']??'' }} km/L</p>@endif<small>Regra: {{ str_replace('_',' ',$a->rule_key) }} · {{ $a->last_detected_at?->format('d/m/Y H:i') }}</small></div></article>@empty<div class="consistency-empty">Nenhuma inconsistência encontrada para os filtros selecionados.</div>@endforelse</section>{{ $alerts->links() }}</div>
